def load_posts(apps, schema_editor):
    BlogPost = apps.get_model("adminpanel", "BlogPost")
    now = timezone.now()
    for row in POSTS:
        existing = BlogPost.objects.filter(slug=row["slug"]).first()
        if existing is None:
            BlogPost.objects.create(
                slug=row["slug"],
                title=row["title"],
                category=row["category"],
                author_name=row["author_name"],
                read_minutes=row["read_minutes"],
                content=row["content"],
                excerpt=row["content"].strip().split("\n\n")[0][:280],
                is_published=True,
                published_at=now,
            )
            continue
        # Only fill in a stub. An editor's longer version is the newer truth.
        if len(existing.content or "") >= len(row["content"]):
            continue
        existing.content = row["content"]
        if not (existing.excerpt or "").strip():
            existing.excerpt = row["content"].strip().split("\n\n")[0][:280]
        existing.save(update_fields=["content", "excerpt"])


def noop(apps, schema_editor):
    """Intentionally does nothing -- see module docstring."""


